def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {ignore, replace, upsert}; trigger in {none, after_insert_log};
    # channel in {changes, total_changes, total_changes_both}.
    # We simulate each candidate and keep those matching all receipts.

    def simulate(put_mode, trig, chan, actions):
        # state: dict key->value for committed; pending per connection
        committed = {}
        # transaction state per connection: None or dict of pending ops
        tx = {"main": None, "other": None}
        # counters
        changes_main = 0
        changes_other = 0
        total_main = 0
        total_other = 0
        # log rows count (trigger)
        log = 0
        # channel value at end
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx[conn] = {}
            elif op == "commit":
                if tx[conn] is not None:
                    for k, v in tx[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            elif op == "put":
                key = act["key"]
                val = act["value"]
                # determine current visible value for this connection
                if tx[conn] is not None:
                    cur = tx[conn].get(key, committed.get(key))
                else:
                    cur = committed.get(key)
                # apply put mode
                if cur is None:
                    # insert
                    newval = val
                    inserted = True
                else:
                    if put_mode == "ignore":
                        inserted = False
                        newval = cur
                    elif put_mode == "replace":
                        inserted = True
                        newval = val
                    else:  # upsert
                        inserted = True
                        newval = val
                if inserted:
                    if tx[conn] is not None:
                        tx[conn][key] = newval
                    else:
                        committed[key] = newval
                    # count changes
                    if conn == "main":
                        changes_main += 1
                        total_main += 1
                    else:
                        changes_other += 1
                        total_other += 1
                    if trig:
                        log += 1
            elif op == "update":
                key = act["key"]
                val = act["value"]
                if tx[conn] is not None:
                    cur = tx[conn].get(key, committed.get(key))
                else:
                    cur = committed.get(key)
                if cur is not None:
                    if tx[conn] is not None:
                        tx[conn][key] = val
                    else:
                        committed[key] = val
                    if conn == "main":
                        changes_main += 1
                        total_main += 1
                    else:
                        changes_other += 1
                        total_other += 1
                    if trig:
                        log += 1
            elif op == "delete":
                key = act["key"]
                if tx[conn] is not None:
                    cur = tx[conn].get(key, committed.get(key))
                else:
                    cur = committed.get(key)
                if cur is not None:
                    if tx[conn] is not None:
                        tx[conn][key] = None
                    else:
                        committed.pop(key, None)
                    if conn == "main":
                        changes_main += 1
                        total_main += 1
                    else:
                        changes_other += 1
                        total_other += 1
                    if trig:
                        log += 1
        # channel value
        if chan == "changes":
            ch = changes_main
        elif chan == "total_changes":
            ch = total_main
        else:
            ch = total_main + total_other
        return ch, len(committed), sum(committed.values())

    # filter candidates
    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for trig in [False, True]:
            for chan in ["changes", "total_changes", "total_changes_both"]:
                ok = True
                for rec in hist:
                    ch, cc, cs = simulate(put_mode, trig, chan, rec["actions"])
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trig, chan))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for put_mode, trig, chan in candidates:
        ch, cc, cs = simulate(put_mode, trig, chan, actions)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

